const { discoverTasks } = await mod(`${pk}/contract/discover.mjs`);
const { loadConfig } = await mod('engine/checks/helpers/repo-context.mjs');
const { collectSignalsForTask } = await mod(`${pk}/signals/for-task.mjs`);
const writes = [];
let fakeNo = 900000;
const fetchImpl = async (url, init = {}) => {
  const method = init.method ?? 'GET';
  if (method === 'GET') return fetch(url, init);
  const body = init.body ? JSON.parse(init.body) : undefined;
  writes.push({ method, path: url.replace('https://api.github.com', ''), body });
  const json = /\/issues$/.test(url) && method === 'POST' ? { number: ++fakeNo, id: fakeNo } : {};
  return new Response(JSON.stringify(json), { status: method === 'POST' ? 201 : 200 });
};
