const config = loadConfig(root);
const { tasks, errors } = await discoverTasks(root, config);
for (const e of errors) console.log(`! ${e.what}`);
const times = {};
const phase = (name) => { const t = Date.now(); return () => { times[name] = Date.now() - t; }; };
const t0 = Date.now();
const { problems } = await schedulerRun({
  gh, repo, root, config, tasks, defaultBranch: 'main', now: new Date().toISOString(),
  collectSignalsFor: ({ items }) => collectSignalsForTask({ gh, repo, root, config, defaultBranch: 'main', items }),
  wake, phase, setOutput: (k, v) => console.log(`[output] ${k}=${v}`),
});
console.log('\n=== DRY RUN SUMMARY ===');
console.log(`tasks discovered: ${tasks.length}; wall ${Date.now() - t0}ms; phases ${JSON.stringify(times)}; api calls ${apiCallCount()}`);
console.log(`problems: ${JSON.stringify(problems)}`);
console.log(`withheld writes: ${writes.length}`);
for (const w of writes) console.log(`  ${w.method} ${w.path} ${w.body ? JSON.stringify(w.body).slice(0, 160) : ''}`);
EOF
